var i=278;var a=[{id:`cooking-278-01`,theoryId:278,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Why do professional kitchens plan an order backward from service time?`,ua:`Навіщо професійні кухні планують замовлення у зворотному напрямку від часу подачі?`},explanation:{en:`Different components have different cooking times and holding constraints.`,ua:`Різні компоненти мають різний час приготування та обмеження щодо очікування.`},options:[{id:`a`,text:{en:`To eliminate communication between stations`,ua:`Щоб усунути комунікацію між станціями`}},{id:`b`,text:{en:`To finish components together with appropriate quality and temperature`,ua:`Щоб компоненти були готові разом з належною якістю й температурою`}},{id:`c`,text:{en:`To start every component at exactly the same time`,ua:`Щоб запускати всі компоненти точно одночасно`}}],answer:{optionIds:[`b`]}},{id:`cooking-278-02`,theoryId:278,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`A crispy fried garnish can usually wait as long as cooked rice without any quality loss.`,ua:`Хрусткий смажений гарнір зазвичай може чекати так само довго, як і рис, без втрати якості.`},explanation:{en:`Crispy surfaces often lose texture as they sit and absorb moisture.`,ua:`Хрусткі поверхні часто втрачають текстуру, коли лежать і вбирають вологу.`},answer:{value:!1}},{id:`cooking-278-03`,theoryId:278,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match service tasks to timing choices.`,ua:`Поєднайте завдання сервісу з рішеннями щодо часу.`},explanation:{en:`Choose timing based on preparation duration and allowable holding.`,ua:`Вибирайте час за тривалістю приготування та допустимим очікуванням.`},leftItems:[{id:`l1`,text:{en:`Long-cooking grain`,ua:`Крупа тривалого приготування`}},{id:`l2`,text:{en:`Pan-seared fish`,ua:`Риба, обсмажена на сковороді`}},{id:`l3`,text:{en:`Butter-mounted sauce`,ua:`Соус, завершений маслом`}}],rightItems:[{id:`r2`,text:{en:`Finish close to plating time`,ua:`Завершити ближче до подачі`}},{id:`r3`,text:{en:`Finish shortly before service`,ua:`Завершити незадовго до подачі`}},{id:`r1`,text:{en:`Start ahead with appropriate safe holding`,ua:`Почати раніше з належним безпечним зберіганням`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-278-04`,theoryId:278,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Fish requires 8 minutes, vegetables 5 and plating 2. All must be served at 19:00. What is the best plan?`,ua:`Рибі потрібно 8 хвилин, овочам 5, оформленню 2. Подача має бути о 19:00. Який план найкращий?`},explanation:{en:`Backward scheduling aligns finish time; actual station capacity and safe holding still require checking.`,ua:`Зворотне планування узгоджує готовність; також потрібно враховувати можливості станцій і безпечне зберігання.`},options:[{id:`a`,text:{en:`Begin fish around 18:50, vegetables around 18:53, and plate near 18:58`,ua:`Почати рибу близько 18:50, овочі — 18:53, оформлення — близько 18:58`}},{id:`b`,text:{en:`Prepare everything by 18:00 and leave it at room temperature`,ua:`Приготувати все до 18:00 і залишити за кімнатної температури`}},{id:`c`,text:{en:`Start fish and vegetables at 19:00`,ua:`Почати рибу й овочі о 19:00`}}],answer:{optionIds:[`a`]}},{id:`cooking-278-05`,theoryId:278,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which actions improve coordinated service?`,ua:`Які дії покращують узгодженість видачі?`},explanation:{en:`Communication and temperature-aware scheduling protect both quality and safety.`,ua:`Комунікація та планування з урахуванням температури зберігають якість і безпеку.`},options:[{id:`a`,text:{en:`Confirm allergy-related modifications`,ua:`Підтверджувати зміни через алергію`}},{id:`b`,text:{en:`Hold cooked food at any temperature while waiting`,ua:`Тримати приготовану їжу за будь-якої температури під час очікування`}},{id:`c`,text:{en:`Use clear fire and ready signals`,ua:`Використовувати чіткі сигнали початку й готовності`}},{id:`d`,text:{en:`Warn stations promptly about delays`,ua:`Швидко попереджати станції про затримки`}}],answer:{optionIds:[`c`,`d`,`a`]}},{id:`cooking-278-06`,theoryId:278,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`An order must be plated by 19:10. The final cooking step takes 12 minutes and plating takes 3 minutes. How many minutes before 19:10 must cooking start?`,ua:`Замовлення потрібно оформити до 19:10. Фінальне приготування триває 12 хвилин, оформлення — 3. За скільки хвилин до 19:10 потрібно почати готувати?`},explanation:{en:`12 + 3 = 15 minutes before the target time, ignoring additional buffers.`,ua:`12 + 3 = 15 хвилин до цільового часу без урахування додаткового резерву.`},numericInput:{unit:`min`,unitLabel:{en:`minutes`,ua:`хвилин`},allowDecimals:!1},answer:{value:15,tolerance:0,unit:`min`}}];var n={theoryId:278,exercises:a};export{n as default,a as exercises,i as theoryId};